// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-extract-color-palette-from-image' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>大好きな色を持つ写真があり、その色をWebサイトやポスター、ブランドのパレットとして必要としています。目でコピーするのは遅くて不正確です。</p>\n<p>この記事では、画像からカラーパレットを抽出する手順を5ステップで解説します。アップロードし、スウォッチ数を選び、割合を読み、結果をコピーまたはダウンロードします。</p>\n<p>慣れれば1分もかかりません。ソフトのインストールも、アカウント登録も、サーバーへのファイルのアップロードも不要です。</p>\n<h2 id=\"what-you-need\">始める前に用意するもの</h2>\n<p>色を持つ画像が必要です。JPG、PNG、WebP形式で、最大20MBまで使えます。写真や商品写真、スクリーンショット、アート作品のいずれも使えます。</p>\n<p>パレットの用途を知っておきましょう。Webサイトのテーマには4〜6色、ブランドアイデンティティにはもう少し多く、ムードボードには12色すべて使えます。</p>\n<p>ソフトはブラウザだけで十分です。Chrome、Safari、Firefox、Edgeがパソコンでもスマホでも動作し、拡張機能は不要です。</p>\n<p>最後に、最もきれいな元のファイルを使いましょう。再圧縮されたコピーや写真のスクリーンショットは、ピクセル値をわずかにずらして、結果のパレットを変えることがあります。</p>\n<h2 id=\"step-1-upload-or-paste\">ステップ1：画像をアップロードする・スクリーンショットを貼り付ける</h2>\n<p><a href=\"/ja/iro-paretto-chushutsu/\">画像カラーパレット抽出ツール</a>を開き、画像をアップロード欄にドラッグします。クリックしてデバイスからファイルを選ぶこともできます。</p>\n<p>色が今まさに画面に表示されているなら、スクリーンショットを撮ってCtrl+Vで貼り付けます。ツールはクリップボードの画像を直接受け付けるため、見ているWebサイトやアプリからパレットを抽出できます。</p>\n<p>画像が読み込まれるとすぐにパレットが表示され、既定値の6スウォッチから始まります。各スウォッチには色と、そのコード、画像に占める割合が表示されます。</p>\n<p>間違ったファイルを上げてしまっても大丈夫です。ツールから別の写真に切り替えれば、古いパレットは置き換わり、ページを再読み込みせずに作業を続けられます。</p>\n<h2 id=\"step-2-choose-swatch-count\">ステップ2：スウォッチ数を選ぶ</h2>\n<p>スライダーを動かして、スウォッチ数を3から12の間で設定します。動かすたびにパレットは瞬時に再構築されるため、数秒で数を比べられます。</p>\n<p>まず6から始めて、結果を見ましょう。2つのスウォッチがほぼ同じに見えたら、数を4または5に下げると、重複が1つのすっきりした色に統合されるのが分かります。</p>\n<p>大切なアクセントカラーが欠けている場合は、数を12に向けて上げます。スウォッチが多くなれば、小さな細部も独自の箱を持つため、小さなネオンサインや小さな花が現れることがあります。</p>\n<p>1つの正しい数はありません。最小限のWebサイトは3または4を求め、豊かなブランドボードは8または10を求め、スライダーはプロジェクトに合う数を見つけるためにあります。</p>\n<h2 id=\"step-3-read-the-percentages\">ステップ3：割合とストリップを読む</h2>\n<p>各スウォッチには、その色が画像のどれだけを占めるかを示す割合バッジが付いています。最も大きな割合が主要色で、最も小さなものがアクセントです。</p>\n<p>割合は、デザインの階層として読みましょう。主要色が最も多くのスペースを取り、副色が支える役割を担い、最も小さな色はハイライトだけに使います。</p>\n<p>スウォッチの下にある割合表示のカラーストリップも見ましょう。同じ階層をバーとして示し、区画の幅が割合と一致するため、バランスが判断しやすいです。</p>\n<p>ストリップのほとんどが1色なら、その写真には強い主要トーンがあり、デザインは落ち着いた印象になります。ストリップが均等に分かれていれば、写真は忙しく、デザインの他の場所で控えめにする必要があります。</p>\n<h2 id=\"step-4-copy-css-or-json\">ステップ4：パレットをCSSまたはJSONでコピーする</h2>\n<p>CSSコピーをクリックすると、すべてのスウォッチがCSSカスタムプロパティとしてコピーされます。変数は順番に名付けられ、それぞれにHEX値が入っていて、スタイルシートに直接貼れます。</p>\n<p>パレットがスタイルシートではなくコードに流れ込む場合は、JSONコピーをクリックします。JSONには、各色のHEX、RGB、HSL値と割合が、スクリプトが解析できる形で含まれています。</p>\n<p>スウォッチ数を変えると、書き出しも更新されます。再アップロードせずに6色から4色に切り替えられ、コピーされるCSSやJSONはすぐに新しいセットを反映します。</p>\n<p>書き出しはプロジェクトと一緒に保存しましょう。ブラウザのタブの中だけにあるパレットは、タブを閉じれば消えてしまいますが、保存したファイルはプロジェクトが再開したときにそこにあります。</p>\n<h2 id=\"step-5-download-palette-card\">ステップ5：パレットカードをダウンロードする</h2>\n<p>パレットPNGダウンロードをクリックすると、パレットカードが生成されます。元の写真と、その下に並べられたスウォッチストリップと色です。抽出の視覚的な要約です。</p>\n<p>カードをクライアントやチームと共有しましょう。パレットの写真は、HEXコードの一覧より速く伝わります。特にコードを読まない人にはそうです。</p>\n<p>ムードボードやブランド文書、プレゼンテーションでカードを使いましょう。色の由来を示すことで信頼が生まれます。クライアントは元の写真を見ることができるからです。</p>\n<p>カードはプロジェクトのファイルと一緒に保管します。数か月後にパレットが疑問視されたとき、カードが元の写真と根拠を1枚の画像で示してくれます。</p>\n<h2 id=\"extracting-from-a-photo\">写真からパレットを抽出する</h2>\n<p>写真はパレットの最良の素材です。現実の世界の色がすでに一緒に機能しているからです。夕焼けや街並み、商品写真が、配色全体を提供してくれます。</p>\n<p>写真の中で最も大きな平らな部分から始めましょう。青空や塗られた壁、無地の服は、抽出ツールが高く順位付けし、確実に評価する安定した色を与えます。</p>\n<p>混ざった光に注意しましょう。片側に暖かい日光、もう片側に冷たい影がある写真は、同じ色の2つのバージョンを生み、パレットでは重複に見えます。</p>\n<p>そうなった場合は、求める雰囲気に合うバージョンを選びます。暖かい方は居心地の良いデザインに、冷たい方はすっきりしたデザインに合い、両方を残すとたいていパレットが濁ります。</p>\n<h2 id=\"extracting-from-a-logo\">ロゴからパレットを抽出する</h2>\n<p>ロゴは正確さが求められるケースです。ブランドのパレットは正確に一致しなければなりません。まず最も高画質なロゴファイルを用意し、できればベタ塗りの背景のPNGを使いましょう。</p>\n<p>透明な背景は抽出ツールが処理し、完全に透明なピクセルを無視します。ただ、透明な背景のロゴでも、縁が半透明だとおかしな結果になることがあります。</p>\n<p>最もきれいな結果を得るには、まずロゴを白やブランドカラーの背景に置いてから、そのバージョンから抽出します。そうすればパレットは透明度の処理ではなく、ロゴの色を反映します。</p>\n<p>重要な色は、後で<a href=\"/ja/gazou-iro-picker/\">画像カラーピッカー</a>で検証しましょう。ピッカーは正確なピクセルを読むため、抽出された値がグラデーションの平均で少しずれているように見えるときに、ブランドカラーを確認できます。</p>\n<h2 id=\"extracting-from-a-screenshot\">スクリーンショットからパレットを抽出する</h2>\n<p>スクリーンショットは、気に入ったWebサイトやアプリのパレットを取り込む最速の方法です。画面をキャプチャしてCtrl+Vで貼り付けると、パレットが表示されます。</p>\n<p>抽出ツールは、画面の色を占める割合順に並べるため、背景と主な面が支配し、ボタンやリンクの色が小さなアクセントとして現れます。</p>\n<p>テキストには注意しましょう。文字だらけのスクリーンショットは、文字からグレーや黒のスウォッチを生みます。これらはデザインパレットの一部ではなく、無視すべきです。</p>\n<p>独創性の問題も覚えておきましょう。別のサイトに着想を得たパレットは問題ありませんが、競合ブランドのパレットをそのままコピーすることは、クライアントの仕事では良くない選択です。</p>\n<h2 id=\"when-an-accent-goes-missing\">小さなアクセントが消えたとき</h2>\n<p>小さなアクセントは、抽出ツールが色を占める割合で順位付けするため、パレットから消えることがあります。写真の1%しか占めないネオンサインは、隣の色に折り込まれるかもしれません。</p>\n<p>まずスウォッチ数を12に向けて上げましょう。スウォッチが多くなれば、小さな細部も独自の箱を持つため、アクセントが現れる可能性が高くなります。</p>\n<p>それでも現れない場合は、スポイトで取りましょう。画像カラーピッカーが正確なピクセルを読み、その色を抽出したパレットに手作業で追加できます。</p>\n<p>手作業で追加するときは、アクセントの割合を控えておきましょう。1%のアクセントはハイライトの色であって主要色ではなく、大きな面積に使えばデザインが圧倒されてしまいます。</p>\n<h2 id=\"fixing-duplicate-shades\">パレットの重複した色合いを直す</h2>\n<p>ほぼ同じに見える2つのスウォッチは、たいていグラデーションから生まれます。空が明るい青から少しずつ濃い青へと変化するようなものです。アルゴリズムはグラデーションを2つの箱に分割します。</p>\n<p>デザインに合う色合いを残して、もう片方を外しましょう。青が1つのパレットは、誰も区別できない青が2つあるパレットよりすっきりします。</p>\n<p>代わりに、スウォッチ数を下げることもできます。6色ではグラデーションはたいてい1つの箱に収まり、重複は手作業の編集なしで自然に消えます。</p>\n<p>重複を外すときは、割合を確認しましょう。残した色が、デザインの中で2つの色合いが合わせて占めていた割合を担うべきです。2つの色合いを合わせると、写真のそれだけの部分を占めていたからです。</p>\n<h2 id=\"using-the-palette-in-design-tools\">Figma・Canva・CSSでパレットを使う</h2>\n<p>Figmaでは、各HEXコードをカラースタイルに貼り付けます。スウォッチごとに1つのスタイルを作り、背景や主要色、アクセントのように役割で名前を付ければ、チームが一貫して使えます。</p>\n<p>Canvaでは、HEXコードをブランドキットや各要素のカラーピッカーに貼り付けます。そうすればパレットは、アカウント内のすべてのデザインで利用できるままになります。</p>\n<p>CSSでは、コピーしたカスタムプロパティをスタイルシートに貼り付け、変数をあらゆる場所で参照します。変数によるパレットは更新が簡単です。1つの値を変えれば、サイト全体が更新されます。</p>\n<p>デザインシステムでは、JSON書き出しを信頼できる情報源として保存しましょう。トークンのパイプラインがそれを読み、同じファイルからCSSやFigmaの変数、ドキュメントを生成できます。</p>\n<h2 id=\"switching-count-without-reupload\">再アップロードなしで数を切り替える</h2>\n<p>画像を再アップロードすることなく、いつでもスウォッチ数を変えられます。スライダーを動かすと、同じ画像データからパレットが瞬時に再構築されます。</p>\n<p>これは数を比べるのに便利です。4、次に6、次に8と試し、パレットがどう細部を得て、どう重複し始めるかを見ましょう。正しい数は、たいてい重複が現れる直前です。</p>\n<p>いくつかのバージョンを残したい場合は、変更のたびにCSSやJSONをコピーしましょう。書き出しは常に現在の数を反映するため、気に入ったバージョンはスライダーを再び動かすと失われることがあります。</p>\n<p>新しい画像をアップロードすると、古いパレットは自動的に消えます。ツールがすっきり保たれますが、残したいパレットは画像を切り替える前に保存すべきだということです。</p>\n<h2 id=\"extracting-from-product-photos\">商品写真からパレットを抽出する</h2>\n<p>商品写真は特別なケースです。パレットは写真だけでなく、商品に役立たなければなりません。白背景の商品写真から抽出すると、パレットは白に支配され、商品そのものについてほとんど何も教えてくれません。</p>\n<p>商品の仕事では、スタジオ写真ではなくライフスタイル写真から抽出しましょう。部屋や屋外で使われている商品を撮影した写真は、その文脈の色を持ち、その色がより良いパレットになります。</p>\n<p>スタジオ写真しかない場合は、抽出する前に商品をきつく切り取りましょう。白い背景を取り除けば、抽出ツールは周囲の空白ではなく商品の色を順位付けします。</p>\n<p>パレットを、知っている商品の色と照らし合わせましょう。商品のブランドカラーが欠けていたり、ずれていたりする場合は、スポイトで検証してパレットに手作業で追加します。</p>\n<p>商品のパレットは、リスティングやパッケージ、広告に流れ込むため、ふだんより一貫性が重要です。CSSやJSONの書き出しを商品ファイルと一緒に保存し、商品が登場するすべてのチャネルで同じパレットを使いましょう。</p>\n<p>商品のシリーズでは、各商品からパレットを抽出して比べましょう。パレットの系統を共有する商品はシリーズに見え、無関係なパレットの商品はランダムな寄せ集めに見えます。</p>\n<p>季節商品には季節のパレットがふさわしいです。夏の商品写真は明るく暖かい色を与え、同じ商品の冬バージョンは深い色合いを与え、パレットは季節とともに変わるべきです。</p>\n<p>最後に、マーケットプレイスのリスティング自体でパレットをテストしましょう。デザインツールでは良く見えるパレットも、マーケットプレイスの白い背景や画面の色の前では失敗することがあります。公開する前に、実際に置いて確認します。</p>\n<h2 id=\"quick-reference-checklist\">チェックリスト</h2>\n<p>最もきれいな元のファイルをアップロードし、スウォッチ数を設定し、割合とストリップを読み、CSSまたはJSONでコピーして、パレットカードをダウンロードします。</p>\n<p>似た色を整理し、欠けたアクセントはスポイトで取り戻し、タブを閉じる前に書き出しをプロジェクトと一緒に保存します。</p>\n<p>詳しい背景は<a href=\"/ja/blog/iro-paretto-chushutsu-kanzen-gaido/\">画像カラーパレット抽出完全ガイド</a>、デザインのワークフローのコツは<a href=\"/ja/blog/shashin-kara-iro-paretto-dezain/\">写真から作るカラーパレット：デザインワークフローのコツ</a>をご覧ください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"抽出した色のうち、実際に使う色をどう選べばいいですか？","answer":"最も大きな割合の色を主要色として、2番目に大きな色を副色として、最も小さな色をアクセントとして使いましょう。ほとんどのデザインには4〜6色で十分です。似た色を外し、順位が高くても雰囲気に合わない色は使わないようにします。"},{"question":"動画の静止画や映画のフレームからパレットを抽出できますか？","answer":"はい。フレームのスクリーンショットを撮って抽出ツールに貼り付けると、パレットが表示されます。映画の静止画は優れた素材です。撮影監督が配色をていねいに設計しているからです。クライアントの仕事で映画の見た目をそのままコピーするのではなく、着想として使いましょう。"},{"question":"割合を合計しても100%にならないのはなぜですか？","answer":"たいていは、丸めの範囲内で100%になります。各スウォッチの割合は整数に丸めて表示されるため、表示される値の合計が99%や101%になることがあります。裏側の割合は正確で、丸めは表示方法だけのものです。"},{"question":"パレットカードとCSS書き出しの違いは何ですか？","answer":"パレットカードは、写真とスウォッチを示すPNG画像で、人と共有するために作られています。CSS書き出しは、色の変数を含むテキストで、コードに貼るために作られています。クライアントやプレゼンテーションにはカードを、開発者にはCSSを使いましょう。"},{"question":"白黒画像からパレットを抽出できますか？","answer":"はい。ただし結果はグレーの色合いになります。割合は写真の色調構造を示し、モノクロでデザインするときに役立ちます。印象の強い写真から得たグレーのパレットは、最小限のデザインの上品な土台になります。"},{"question":"デザインツールを使わないクライアントと抽出したパレットを共有するにはどうすればいいですか？","answer":"パレットカードのPNGをダウンロードして送りましょう。カードは元の写真とその下のスウォッチを示すため、誰でも色とその由来を見ることができます。HEXコードもメッセージに添えて、クライアントが後で参照できるようにしましょう。"}];
